export type CodeWorkspaceCopyKey = keyof typeof messages;
export type CodeWorkspaceCopy = Record<CodeWorkspaceCopyKey, string>;
export function codeWorkspaceCopy(locale: Locale): CodeWorkspaceCopy {
  const index = LANGUAGES.findIndex(([code]) => code === locale);
  if (index < 0) throw new Error('Unsupported workspace locale');
  return Object.fromEntries(Object.entries(messages).map(([key, row]) => [key, row[index]])) as CodeWorkspaceCopy;
}
